import "server-only";

import { randomUUID } from "node:crypto";
import { z } from "zod";
import { db } from "@/lib/db";
import { BillingError, billingConfig } from "@/lib/billing/config";
import { billingCheckoutUrl, dodoClient } from "@/lib/billing/dodo";
import {
  ensureBillingBinding,
  openCheckoutStates,
  verifyBillingProduct,
} from "@/lib/billing/store";
import { reconcileBillingSubscription } from "@/lib/billing/lifecycle";
import { withUsageTransaction } from "@/lib/usage-ledger";

const checkoutInput = z
  .object({
    plan: z.literal("paid_monthly"),
    idempotencyKey: z.uuid(),
  })
  .strict();
// Hosted sessions last 24h. The upper bound includes the request timeout and a
// safety margin. No new checkout is allowed until this bound AND reconciliation.
const CHECKOUT_RECOVERY_MARGIN_MS = 5 * 60_000;
export const CHECKOUT_RECOVERY_WINDOW_MS =
  24 * 60 * 60_000 + CHECKOUT_RECOVERY_MARGIN_MS;
// expiresAt is the recovery bound, not the hosted link's expiry. Stop returning
// the link one minute before its 24h lifetime ends, keeping recovery unchanged.
const CHECKOUT_URL_EXPIRY_BUFFER_MS = CHECKOUT_RECOVERY_MARGIN_MS + 60_000;

function hasOutstandingSubscription(subscription: {
  status: string;
  cancel_at_next_billing_date: boolean;
  next_billing_date: string;
}) {
  return (
    !["cancelled", "expired", "failed"].includes(subscription.status) ||
    (subscription.status === "cancelled" &&
      subscription.cancel_at_next_billing_date &&
      new Date(subscription.next_billing_date) > new Date())
  );
}

export async function providerSubscriptions(
  customerId: string,
  signal?: AbortSignal,
) {
  const subscriptions = [];
  for await (const item of dodoClient().subscriptions.list(
    {
      customer_id: customerId,
    },
    { signal },
  ))
    subscriptions.push(item);
  return subscriptions;
}

export async function recoverCheckoutAttempt(
  userId: string,
  attemptId: string,
) {
  const attempt = await db.checkoutAttempt.findFirst({
    where: { id: attemptId, userId, status: { in: openCheckoutStates } },
  });
  if (!attempt || Date.now() - attempt.updatedAt.getTime() < 30_000) return;
  const user = await db.user.findUniqueOrThrow({ where: { id: userId } });
  let customerId = user.dodoCustomerId;
  if (!customerId) {
    // A lost customer-create response is recovered by server-generated metadata,
    // never by trusting email identity alone or repeating the creation request.
    const matching = [];
    for await (const customer of dodoClient().customers.list({
      email: user.email,
    })) {
      if (
        customer.metadata?.mailloopUserId === userId &&
        customer.metadata?.checkoutAttemptId === attempt.id
      )
        matching.push(customer);
    }
    if (matching.length > 1)
      throw new BillingError("CUSTOMER_CREATION_CONFLICT");
    customerId = matching[0]?.customer_id ?? null;
    if (customerId)
      await withUsageTransaction(db, userId, async ({ tx }) => {
        const current = await tx.user.findUniqueOrThrow({
          where: { id: userId },
        });
        if (current.dodoCustomerId && current.dodoCustomerId !== customerId)
          throw new BillingError("CUSTOMER_CREATION_CONFLICT");
        await tx.user.update({
          where: { id: userId },
          data: {
            dodoCustomerId: customerId,
            billingStateVersion: { increment: 1 },
          },
        });
      });
  }
  const subscriptions = customerId
    ? await providerSubscriptions(customerId)
    : [];
  const outstanding = subscriptions.filter(hasOutstandingSubscription);
  for (const sub of subscriptions.filter(
    (s) =>
      s.product_id === billingConfig().productId &&
      (s.metadata?.checkoutAttemptId === attempt.id ||
        new Date(s.created_at) >= attempt.createdAt),
  ))
    await reconcileBillingSubscription(userId, sub.subscription_id);
  if (outstanding.length) return; // including an activated but unsettled mandate
  if (attempt.dodoSessionId) {
    const session = await dodoClient().checkoutSessions.retrieve(
      attempt.dodoSessionId,
    );
    // A succeeded/processing checkout with no visible subscription is uncertain,
    // even past the local expiry. Never replace it with a fresh subscription.
    if (
      session.payment_status &&
      !["failed", "cancelled"].includes(session.payment_status)
    )
      return;
  }
  if (new Date() < attempt.expiresAt) return;
  await withUsageTransaction(db, userId, async ({ tx }) => {
    await tx.checkoutAttempt.updateMany({
      where: {
        id: attempt.id,
        userId,
        updatedAt: attempt.updatedAt,
        status: { in: openCheckoutStates },
      },
      data: { status: "EXPIRED", checkoutUrl: null, failureCode: null },
    });
  });
}

export async function createBillingCheckout(userId: string, input: unknown) {
  const parsed = checkoutInput.safeParse(input);
  if (!parsed.success)
    throw new BillingError(
      "INVALID_CHECKOUT",
      "Choose a valid plan and checkout attempt.",
      400,
    );
  const config = billingConfig();
  const client = dodoClient();
  const control = await db.systemControl.findUnique({
    where: { key: "global" },
  });
  if (!control?.billingCheckoutEnabled)
    throw new BillingError(
      "CHECKOUT_DISABLED",
      "Checkout is currently disabled.",
    );
  await verifyBillingProduct();
  const pending = await db.checkoutAttempt.findFirst({
    where: { userId, status: { in: openCheckoutStates } },
  });
  if (pending && pending.expiresAt <= new Date())
    await recoverCheckoutAttempt(userId, pending.id);

  const reservation = await withUsageTransaction(db, userId, async ({ tx }) => {
    await ensureBillingBinding(tx);
    const control = await tx.systemControl.findUnique({
      where: { key: "global" },
    });
    if (!control?.billingCheckoutEnabled)
      throw new BillingError(
        "CHECKOUT_DISABLED",
        "Checkout is currently disabled.",
      );
    const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
    if (user.deletionRequestedAt || user.isSuspended)
      throw new BillingError(
        "ACCOUNT_UNAVAILABLE",
        "This account cannot start checkout.",
        403,
      );
    if (
      await tx.billingSubscription.count({
        where: {
          userId,
          OR: [
            { status: { notIn: ["CANCELLED", "EXPIRED", "FAILED"] } },
            {
              status: "CANCELLED",
              cancelAtPeriodEnd: true,
              periodEnd: { gt: new Date() },
            },
          ],
        },
      })
    )
      throw new BillingError(
        "ALREADY_SUBSCRIBED",
        "Manage your existing subscription in billing settings.",
        409,
      );
    const open = await tx.checkoutAttempt.findFirst({
      where: { userId, status: { in: openCheckoutStates } },
    });
    if (open) {
      if (
        open.status === "READY" &&
        open.checkoutUrl &&
        open.expiresAt.getTime() - CHECKOUT_URL_EXPIRY_BUFFER_MS > Date.now()
      )
        return { user, attempt: open, created: false };
      throw new BillingError(
        "CHECKOUT_PENDING",
        "Your previous checkout is being verified. Try again shortly.",
        409,
      );
    }
    const prior = await tx.checkoutAttempt.findFirst({
      where: { userId, idempotencyKey: parsed.data.idempotencyKey },
    });
    if (prior)
      throw new BillingError(
        "CHECKOUT_ATTEMPT_FINISHED",
        "This checkout attempt has finished. Refresh before trying again.",
        409,
      );
    if (
      (await tx.checkoutAttempt.count({
        where: { userId, createdAt: { gte: new Date(Date.now() - 3600_000) } },
      })) >= 5
    )
      throw new BillingError(
        "CHECKOUT_RATE_LIMIT",
        "Too many checkout attempts. Try again later.",
        429,
      );
    const attempt = await tx.checkoutAttempt.create({
      data: {
        id: randomUUID(),
        userId,
        ownerIdSnapshot: userId,
        productId: config.productId,
        idempotencyKey: parsed.data.idempotencyKey,
        expiresAt: new Date(Date.now() + CHECKOUT_RECOVERY_WINDOW_MS),
        status: user.dodoCustomerId ? "CREATING" : "CUSTOMER_CREATING",
      },
    });
    return { user, attempt, created: true };
  });
  if (!reservation.created)
    return {
      checkoutUrl: billingCheckoutUrl(
        reservation.attempt.checkoutUrl!,
        config.environment,
      ),
    };
  const { attempt } = reservation;
  let customerId = reservation.user.dodoCustomerId;
  let uncertainCreation = false;
  try {
    if (!customerId) {
      uncertainCreation = true;
      const customer = await client.customers.create(
        {
          email: reservation.user.email,
          name: reservation.user.name || reservation.user.email,
          metadata: { mailloopUserId: userId, checkoutAttemptId: attempt.id },
        },
        { maxRetries: 0 },
      );
      customerId = customer.customer_id;
      await withUsageTransaction(db, userId, async ({ tx }) => {
        const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
        if (user.dodoCustomerId && user.dodoCustomerId !== customerId)
          throw new BillingError("CUSTOMER_CREATION_CONFLICT");
        await tx.user.update({
          where: { id: userId },
          data: {
            dodoCustomerId: customerId,
            billingStateVersion: { increment: 1 },
          },
        });
        await tx.checkoutAttempt.updateMany({
          where: { id: attempt.id, userId },
          data: { status: "CREATING" },
        });
      });
      uncertainCreation = false;
    }
    const currentSubscriptions = await providerSubscriptions(customerId);
    if (currentSubscriptions.some(hasOutstandingSubscription))
      throw new BillingError(
        "ALREADY_SUBSCRIBED",
        "Manage your existing subscription in billing settings.",
        409,
      );
    // The final owner check commits before the outbound request. Deletion racing
    // after this point retains the attempt until it expires and cancels any late
    // subscription; it can never remove the account first.
    await withUsageTransaction(db, userId, async ({ tx }) => {
      const current = await tx.user.findUniqueOrThrow({
        where: { id: userId },
      });
      const control = await tx.systemControl.findUnique({
        where: { key: "global" },
      });
      if (!control?.billingCheckoutEnabled)
        throw new BillingError(
          "CHECKOUT_DISABLED",
          "Checkout is currently disabled.",
        );
      if (current.deletionRequestedAt || current.isSuspended)
        throw new BillingError(
          "ACCOUNT_UNAVAILABLE",
          "Account unavailable.",
          403,
        );
      await tx.checkoutAttempt.updateMany({
        where: { id: attempt.id, userId, status: "CREATING" },
        data: { failureCode: "CHECKOUT_REQUEST_STARTED" },
      });
    });
    uncertainCreation = true;
    const session = await client.checkoutSessions.create(
      {
        // Let the hosted billing country select currency. A forced USD value
        // converts the India INR rule back to dollars instead of charging INR.
        product_cart: [{ product_id: config.productId, quantity: 1 }],
        customer: { customer_id: customerId },
        metadata: { mailloopUserId: userId, checkoutAttemptId: attempt.id },
        return_url: `${config.origin}/usage/return`,
        cancel_url: `${config.origin}/usage`,
        feature_flags: {
          allow_customer_editing_email: false,
          allow_customer_editing_country: true,
          allow_currency_selection: false,
          allow_editing_addons: false,
          allow_discount_code: false,
        },
      },
      { maxRetries: 0 },
    );
    if (!session.checkout_url) throw new BillingError("CHECKOUT_URL_MISSING");
    const checkoutUrl = billingCheckoutUrl(
      session.checkout_url,
      config.environment,
    );
    const available = await withUsageTransaction(db, userId, async ({ tx }) => {
      const current = await tx.user.findUniqueOrThrow({
        where: { id: userId },
      });
      await tx.checkoutAttempt.updateMany({
        where: { id: attempt.id, userId, status: { in: openCheckoutStates } },
        data: {
          status: "READY",
          dodoSessionId: session.session_id,
          checkoutUrl,
          failureCode: null,
          expiresAt: new Date(Date.now() + CHECKOUT_RECOVERY_WINDOW_MS),
        },
      });
      return !current.deletionRequestedAt && !current.isSuspended;
    });
    if (!available)
      throw new BillingError(
        "ACCOUNT_UNAVAILABLE",
        "Account unavailable.",
        403,
      );
    return { checkoutUrl };
  } catch (error) {
    await db.checkoutAttempt.updateMany({
      where: {
        id: attempt.id,
        userId,
        status: { in: ["CUSTOMER_CREATING", "CREATING"] },
      },
      data: {
        status: uncertainCreation ? "UNKNOWN" : "FAILED",
        failureCode: uncertainCreation
          ? "PROVIDER_CREATION_UNCERTAIN"
          : "CHECKOUT_PREPARATION_FAILED",
      },
    });
    if (error instanceof BillingError) throw error;
    throw new BillingError(
      "CHECKOUT_UNCERTAIN",
      "Checkout could not be confirmed. Your previous attempt will be verified before another is created.",
    );
  }
}

export async function createBillingPortal(userId: string) {
  const config = billingConfig();
  const customerId = await withUsageTransaction(db, userId, async ({ tx }) => {
    await ensureBillingBinding(tx);
    const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
    if (user.deletionRequestedAt || !user.dodoCustomerId)
      throw new BillingError(
        "BILLING_ACCOUNT_UNAVAILABLE",
        "No billing account is available.",
        409,
      );
    return user.dodoCustomerId;
  });
  const portal = await dodoClient().customers.customerPortal.create(
    customerId,
    { return_url: `${config.origin}/settings#plan`, send_email: false },
  );
  const url = new URL(portal.link);
  if (
    url.protocol !== "https:" ||
    url.hostname !== "test.customer.dodopayments.com" ||
    url.username ||
    url.password ||
    url.port
  )
    throw new BillingError("INVALID_PORTAL_URL");
  return { portalUrl: url.toString() };
}
